function logicalPin(b,v){const c=catalog.find(c=>c.type===b.type),name=c.pins.find(p=>p==='D'+v||p==='GPIO'+v||p==='GP'+v||p===v);if(!name)throw Error('הפורט אינו בפרופיל הלימודי: '+v);return name}
function execute(stmt){const b=board();if(stmt.kind==='var'){vars[stmt.name]=tokenValue(stmt.expr);return 0}const args=stmt.args.map(tokenValue);switch(stmt.fn){case'pinMode':{const p=logicalPin(b,args[0]);pinModes[p]=args[1];break}case'digitalWrite':case'analogWrite':{const p=logicalPin(b,args[0]);if(pinModes[p]!==1)throw Error('יש להגדיר OUTPUT לפני כתיבה ל־'+p);if(stmt.fn==='analogWrite'&&(args[1]<0||args[1]>255))throw Error('PWM בטווח 0–255 בלבד');pinState[p]=stmt.fn==='analogWrite'?args[1]/255:args[1]?1:0;break}case'delay':if(args[0]<0||args[0]>60000)throw Error('delay בטווח 0–60000 ms');return Math.max(10,args[0]);case'Serial.print':log(args[0],false);break;case'Serial.println':log(args[0]);break;case'Serial.begin':log('Serial '+args[0]+' baud (virtual)');break}return 10}
function initializeCode(){const b=board();if(!b)throw Error('הוסיפו לוח לפני הרצת קוד');if(catalog.find(c=>c.type===b.type).python)throw Error('Python זמין לעריכה וייצוא בלבד');b.code=$('editor').value;program=compileCode(b.code);vars={};pinState={};pinModes={};pc=0;stepCount=0;for(const stmt of program.setup){if(stmt.fn==='delay')throw Error('delay ב־setup אינו נתמך במפרש הזה');execute(stmt)}if(!program.loop.length)throw Error('loop ריקה');codeStart=Date.now();showPins()}
function codeFail(e){stopCode(true);log('ERROR: '+e.message);if($('codestatus'))$('codestatus').textContent='שגיאת קוד';toast(e.message)}
function tickCode(){try{const wait=execute(program.loop[pc]);pc=(pc+1)%program.loop.length;stepCount++;running=true;update();showPins();if($('codestatus'))$('codestatus').textContent='פועל · '+stepCount+' צעדים';codeTimer=setTimeout(tickCode,wait)}catch(e){codeFail(e)}}
function runCode(){stopCode(false);try{initializeCode();log('▶︎ GPIO simulation started');tickCode()}catch(e){codeFail(e)}}
function stopCode(reset=true){if(codeTimer!==null)clearTimeout(codeTimer);codeTimer=null;if(reset){program=null;pinState={};running=false;update();showPins();if($('codestatus'))$('codestatus').textContent='נעצר'}}
function stepCode(){if(codeTimer!==null){clearTimeout(codeTimer);codeTimer=null}try{if(!program)initializeCode();execute(program.loop[pc]);pc=(pc+1)%program.loop.length;stepCount++;running=true;update();showPins();$('codestatus').textContent='צעד '+stepCount}catch(e){codeFail(e)}}
function showPins(){if(!$('pinmonitor'))return;const b=board();$('pinmonitor').innerHTML=b?catalog.find(c=>c.type===b.type).pins.filter(p=>/^(D\d|GPIO|GP\d)/.test(p)).map(p=>`<span class="${pinState[p]?'high':''}">${p} <b>${pinState[p]?(pinState[p]*100).toFixed(0)+'%':'LOW'}</b></span>`).join(''):''}
function connected(a,b){const seen=new Set([a]),queue=[a];while(queue.length){const at=queue.shift();if(at===b)return true;for(const w of wires){const k=w.map(p=>p.id+':'+p.pin);if(k.includes(at)){const to=k[0]===at?k[1]:k[0];if(!seen.has(to)){seen.add(to);queue.push(to)}}}}return false}
function readPin(v,analog){const b=board(),bc=catalog.find(c=>c.type===b.type),p=bc.pins.indexOf(logicalPin(b,v));for(const n of nodes){const c=catalog.find(c=>c.type===n.type);if(!c.input)continue;const out=c.pins.indexOf(c.pins.includes('AO')?'AO':'OUT');if(connected(b.id+':'+p,n.id+':'+out)){const supply=c.pins.indexOf('VCC'),gnd=c.pins.indexOf('GND');if(!connected(n.id+':'+gnd,b.id+':'+bc.pins.indexOf('GND'))||!connected(n.id+':'+supply,b.id+':'+(bc.pins.length-2)))throw Error('חברו VCC ו־GND לחיישן');const fraction=digitalSensors.has(n.type)?Math.min(1,Math.max(0,n.value)):Math.min(1,Math.max(0,n.value/100));return analog?Math.round(fraction*1023):fraction>=.5?1:0}}throw Error('אין חיישן קלט מחובר לפורט '+v)}
const oldSimulate=simulate;simulate=function(){const b=board(),bc=b&&catalog.find(c=>c.type===b.type);if(!b){if(nodes.some(n=>catalog.find(c=>c.type===n.type).sensor))return{current:0,msg:'מודולי חיישן זמינים ללמידה או לקלט דרך קוד. סימולציית DC תומכת ברכיבים הבסיסיים בלבד.'};return oldSimulate()}if(nodes.filter(n=>catalog.find(c=>c.type===n.type).board).length>1)return{current:0,msg:'אפשר להרכיב כמה לוחות. סימולציית GPIO תומכת בלוח פעיל יחיד.'};if(nodes.some(n=>n.type==='source'))return{current:0,msg:'בניסוי GPIO השתמשו בהזנת הלוח בלבד; הסירו מקור DC חיצוני.'};const gpioWires=wires.flat().filter(p=>p.id===b.id&&!['GND','5V','3V3'].includes(bc.pins[p.pin]));const ports=[...new Set(gpioWires.filter(p=>pinModes[bc.pins[p.pin]]===1).map(p=>p.pin))];if(ports.length>1)return{current:0,msg:'חישוב זרם נתמך ליציאת OUTPUT אחת. ניטור שאר הפורטים זמין בעורך.'};if(!ports.length)return{current:0,msg:'כתבו והריצו קוד עם pinMode ו־digitalWrite כדי להפעיל יציאה. חיישנים נקראים דרך Serial Monitor.'};const output=ports[0],oldNodes=nodes,oldWires=wires;try{nodes=nodes.filter(n=>n===b||(!catalog.find(c=>c.type===n.type).sensor));nodes=nodes.map(n=>n===b?{...n,type:'source',value:bc.value*(pinState[bc.pins[output]]||0)}:n);wires=wires.filter(w=>w.every(p=>nodes.some(n=>n.id===p.id))&&w.every(p=>p.id!==b.id||p.pin===output||bc.pins[p.pin]==='GND')).map(w=>w.map(p=>p.id!==b.id?p:{id:p.id,pin:p.pin===output?0:1}));return oldSimulate()}finally{nodes=oldNodes;wires=oldWires}};
const oldUpdate=update;update=function(){oldUpdate();const b=board();if(b)$('voltage').innerHTML=catalog.find(c=>c.type===b.type).value.toFixed(2)+' <em>V</em>';document.body.classList.toggle('sim-running',running)};
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('codeview').onclick=()=>openCode(true);$('mobilecode').onclick=()=>{mobilePanel('workspace');openCode(true)};
function mobilePanel(p){document.body.dataset.mobile=p;document.querySelectorAll('[data-panel]').forEach(b=>b.classList.toggle('active',b.dataset.panel===p))}document.querySelectorAll('[data-panel]').forEach(b=>b.onclick=()=>mobilePanel(b.dataset.panel));mobilePanel('workspace');
const oldSelect=select;select=function(id){oldSelect(id);if(tool==='select'&&innerWidth<=700&&id!=null)mobilePanel('inspector')};
$('newproject').onclick=()=>showModal('<h1>מתחילים פרויקט חדש</h1><p>הפרויקט הפתוח יוחלף. שמרו אותו קודם אם תרצו לחזור אליו.</p><button class="run" id="confirmnew">משטח עבודה ריק</button>');document.addEventListener('click',e=>{if(e.target.id==='confirmnew'){stopCode();nodes=[];wires=[];selected=null;activeBoard=null;idseq=0;$('projecttitle').textContent='הפרויקט החדש שלי';$('codepanel').hidden=true;renderDetail();update();$('modal').close();mobilePanel('library')}});
function boardTemplate(type){stopCode();nodes=[];wires=[];idseq=0;const b=addNode(type,-2,0);const bc=catalog.find(c=>c.type===type);activeBoard=b.id;const r=addNode('resistor',1,-1);const l=addNode('led',2.5,1);activeBoard=b.id;wires=[[{id:b.id,pin:0},{id:r.id,pin:0}],[{id:r.id,pin:1},{id:l.id,pin:0}],[{id:l.id,pin:1},{id:b.id,pin:bc.pins.indexOf('GND')}]];b.code=blinkCode(b);select(b.id);$('projecttitle').textContent=bc.name+' · הבהוב LED';running=false;update();$('modal').close();mobilePanel('workspace');openCode(false)}
function sensorTemplate(){stopCode();nodes=[];wires=[];idseq=0;const b=addNode('arduino_0',-2,0),s=addNode('pot',1.8,0),bc=catalog.find(c=>c.type===b.type);activeBoard=b.id;wires=[[{id:b.id,pin:bc.pins.indexOf('A0')},{id:s.id,pin:1}],[{id:b.id,pin:bc.pins.length-2},{id:s.id,pin:0}],[{id:b.id,pin:bc.pins.length-1},{id:s.id,pin:2}]];b.code='void setup() {\n  pinMode(A0, INPUT);\n  Serial.begin(9600);\n}\nvoid loop() {\n  int reading = analogRead(A0);\n  Serial.println(reading);\n  delay(300);\n}';select(s.id);$('projecttitle').textContent='קריאת פוטנציומטר · Arduino';running=false;update();$('modal').close();mobilePanel('workspace');openCode(false)}
const oldTemplates=$('templates').onclick;$('templates').onclick=()=>{oldTemplates();const el=document.createElement('div');el.className='modalgrid';el.innerHTML=[['arduino_0','Arduino UNO · LED','הבהוב עם digitalWrite, נגד ו־LED.'],['espnew_1','ESP32-S3 · LED','פלט לוגי ברמת 3.3V.'],['rpipico_0','Pico · קוד MicroPython','חיווט, עריכה וייצוא. ללא הרצת Python.'],['rpi_3','Raspberry Pi 5 · GPIO','פרופיל לוגי ללמידה ועריכת קוד.']].map(([t,n,d])=>`<div class="modalcard"><h3>${n}</h3><p>${d}</p><button onclick="boardTemplate('${t}')">פתיחת פרויקט</button></div>`).join('')+'<div class="modalcard"><h3>קוראים חיישן אנלוגי</h3><p>פוטנציומטר, Arduino ו־Serial Monitor חי.</p><button onclick="sensorTemplate()">פתיחת פרויקט</button></div>';$('modalbody').append(el)};
const oldLoadProject=loadProject;loadProject=function(i){stopCode();oldLoadProject(i);activeBoard=nodes.find(n=>catalog.find(c=>c.type===n.type).board)?.id;mobilePanel('workspace');if(!$('codepanel').hidden)openCode()};
const oldProjects=$('projects').onclick;$('projects').onclick=()=>{oldProjects();const bar=document.createElement('div');bar.className='projectio';bar.innerHTML='<button id="exportproject">ייצוא הפרויקט הפתוח JSON</button><label class="importbtn">ייבוא פרויקט<input id="importproject" type="file" accept="application/json,.json" hidden></label>';$('modalbody').prepend(bar);$('exportproject').onclick=()=>download('voltlab-project.json',JSON.stringify({version:2,nodes,wires,idseq},null,2));$('importproject').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>2000000)throw Error('הקובץ גדול מדי');const p=JSON.parse(await file.text());validateProject(p);stopCode();nodes=p.nodes;wires=p.wires;if(typeof p.title==='string')$('projecttitle').textContent=p.title.slice(0,80);idseq=Math.max(0,...nodes.map(n=>n.id));activeBoard=nodes.find(n=>catalog.find(c=>c.type===n.type).board)?.id;select(nodes[0]?.id);update();$('modal').close();mobilePanel('workspace');if(!$('codepanel').hidden)openCode();toast('הפרויקט יובא בהצלחה')}catch(e){toast('לא ניתן לייבא: '+e.message)}}};
function validateProject(p){if(!p||!Array.isArray(p.nodes)||!Array.isArray(p.wires)||p.nodes.length>100||p.wires.length>300)throw Error('מבנה פרויקט לא תקין');const ids=new Set;for(const n of p.nodes){if(!catalog.some(c=>c.type===n.type)||!Number.isInteger(n.id)||n.id<=0||ids.has(n.id)||![n.x,n.z,n.value].every(Number.isFinite)||Math.abs(n.x)>20||Math.abs(n.z)>20||n.value<0||n.value>1e6||n.code!=null&&typeof n.code!=='string'||n.code?.length>100000)throw Error('רכיב לא תקין');ids.add(n.id)}for(const w of p.wires){if(!Array.isArray(w)||w.length!==2)throw Error('חיבור לא תקין');for(const port of w){const n=p.nodes.find(n=>n.id===port?.id);if(!n||!Number.isInteger(port.pin)||port.pin<0||port.pin>=catalog.find(c=>c.type===n.type).pins.length)throw Error('הדק לא תקין')}}}
