const caps=document.createElement('button');caps.id='capabilities';caps.textContent='תמיכה וגרסאות';document.querySelector('nav').append(caps);caps.onclick=()=>showModal('<h1>מה נתמך במעבדה?</h1><p>'+catalog.filter(c=>c.board).length+' פרופילי לוחות ו־'+sensors.length+' מודולי חישה והפעלה. הפרופילים משותפים למשפחות ומציגים GPIO לוגי חלקי. אין תמיכה אוטומטית בכל גרסה פיזית.</p><table><thead><tr><th>תחום</th><th>תמיכה</th></tr></thead><tbody><tr><td>נגדים, LED, מקור, מפסק, LDR, מנוע</td><td>לולאת DC טורית אידאלית</td></tr><tr><td>לוחות Arduino ו־ESP32</td><td>מפרש פקודות GPIO מצומצם; לא אמולציית CPU</td></tr><tr><td>Raspberry Pi / Pico</td><td>הרכבה, הסברים ועריכת/ייצוא Python בלבד</td></tr><tr><td>חיישנים אנלוגיים ודיגיטליים בסיסיים</td><td>הזרקת אות וקריאה דרך קוד</td></tr><tr><td>I²C, SPI, OneWire, אולטרה־סוני, סרוו ומסכים</td><td>הרכבה ולמידה; ללא פרוטוקול פעיל</td></tr><tr><td>קבלים</td><td>בחירת קיבול; נתק במצב DC יציב</td></tr><tr><td>מארזי SMD ומידות</td><td>נגדי SMD מוצגים בגאומטריה נפרדת; אין מידות ייצור מדויקות</td></tr></tbody></table><p>לוח חדש או גרסת חומרה שונה צריכים פרופיל pinout ואימות נפרדים. Wi-Fi, Bluetooth, מערכת הפעלה וספריות חיצוניות אינם מדומים.</p><p><a href="https://docs.arduino.cc/hardware/" target="_blank" rel="noopener">Arduino</a> · <a href="https://docs.espressif.com/projects/esp-idf/en/stable/esp32/api-reference/peripherals/gpio.html" target="_blank" rel="noopener">Espressif</a> · <a href="https://www.raspberrypi.com/documentation/" target="_blank" rel="noopener">Raspberry Pi</a></p>');
const origHelp=$('help').onclick;$('help').onclick=()=>{origHelp();const p=document.createElement('p');p.textContent='בטלפון: סרגל התחתית מעביר בין המעבדה, רכיבים, חקירה וקוד. לחיבור חוטים בחרו כלי חוטים, ואז שני הדקים. אפשר לעבור בין חלוניות בלי לאבד את ההדק הראשון. המטריצה משמשת כמשטח חזותי בלבד; כל חיבור חשמלי חייב חוט מפורש.';$('modalbody').append(p)};
const originalLibrary=renderLibrary;renderLibrary=function(){originalLibrary();document.querySelectorAll('.comp').forEach(btn=>{const c=catalog.find(c=>c.type===btn.dataset.type),badge=document.createElement('small');badge.className='supportbadge';badge.textContent=c.board?(c.python?'הרכבה + Python':'GPIO לימודי'):c.sensor?(c.input?'קלט מדומה':'הרכבה ולמידה'):'DC לימודי';btn.querySelector('span:nth-child(2)').append(badge)})};const baseRun=$('run').onclick;$('run').onclick=()=>{if(codeTimer!==null){stopCode();return}baseRun()};renderLibrary();template('led');mobilePanel('workspace');requestAnimationFrame(render);
